using System;
using System.Runtime.InteropServices;
public class MonitorFix {
  [StructLayout(LayoutKind.Sequential)]
  public struct GAMMARAMP {
    [MarshalAs(UnmanagedType.ByValArray, SizeConst=256)] public ushort[] Red;
    [MarshalAs(UnmanagedType.ByValArray, SizeConst=256)] public ushort[] Green;
    [MarshalAs(UnmanagedType.ByValArray, SizeConst=256)] public ushort[] Blue;
  }
  [DllImport("gdi32.dll")] private static extern bool GetDeviceGammaRamp(IntPtr hDC, out GAMMARAMP ramp);
  [DllImport("gdi32.dll")] private static extern bool SetDeviceGammaRamp(IntPtr hDC, ref GAMMARAMP ramp);
  [DllImport("gdi32.dll", CharSet=CharSet.Unicode)] private static extern IntPtr CreateDC(string driver, string device, string output, IntPtr initData);
  [DllImport("gdi32.dll")] private static extern bool DeleteDC(IntPtr hdc);

  static IntPtr Open(string dev) { return CreateDC("DISPLAY", dev, null, IntPtr.Zero); }

  public static void Dump(string dev) {
    IntPtr dc = Open(dev);
    if (dc == IntPtr.Zero) { Console.WriteLine(dev + ": CreateDC failed"); return; }
    GAMMARAMP r;
    bool ok = GetDeviceGammaRamp(dc, out r);
    Console.WriteLine(string.Format("{0}: get={1} peak R={2} G={3} B={4}", dev, ok, r.Red[255], r.Green[255], r.Blue[255]));
    DeleteDC(dc);
  }

  public static void Apply(string dev, double rr, double gg, double bb) {
    IntPtr dc = Open(dev);
    if (dc == IntPtr.Zero) { Console.WriteLine(dev + ": CreateDC failed"); return; }
    var ramp = new GAMMARAMP { Red = new ushort[256], Green = new ushort[256], Blue = new ushort[256] };
    for (int i = 0; i < 256; i++) {
      ramp.Red[i]   = (ushort)Math.Min(65535, (int)(i * 257.0 * rr));
      ramp.Green[i] = (ushort)Math.Min(65535, (int)(i * 257.0 * gg));
      ramp.Blue[i]  = (ushort)Math.Min(65535, (int)(i * 257.0 * bb));
    }
    bool ok = SetDeviceGammaRamp(dc, ref ramp);
    Console.WriteLine(string.Format("{0}: set={1} R={2} G={3} B={4}", dev, ok, rr, gg, bb));
    DeleteDC(dc);
  }
}
'@
Add-Type -TypeDefinition $src -Language CSharp
Write-Output "=== before ==="
[MonitorFix]::Dump("\\\\.\\DISPLAY5")
[MonitorFix]::Dump("\\\\.\\DISPLAY1")
Write-Output "=== apply: main anti-yellow, secondary neutral ==="
[MonitorFix]::Apply("\\\\.\\DISPLAY5", 0.90, 0.97, 1.0)
[MonitorFix]::Apply("\\\\.\\DISPLAY1", 1.0, 1.0, 0.97)
Write-Output "=== after ==="
[MonitorFix]::Dump("\\\\.\\DISPLAY5")
[MonitorFix]::Dump("\\\\.\\DISPLAY1")

