using System;
using System.Runtime.InteropServices;
public class MonitorGamma {
  [StructLayout(LayoutKind.Sequential, CharSet=CharSet.Unicode)]
  public struct PHYSICAL_MONITOR {
    public IntPtr hPhysicalMonitor;
    [MarshalAs(UnmanagedType.ByValTStr, SizeConst=128)]
    public string Description;
  }
  [StructLayout(LayoutKind.Sequential)]
  public struct RECT { public int Left, Top, Right, Bottom; }
  private delegate bool EnumProc(IntPtr hMonitor, IntPtr hdc, ref RECT rc, IntPtr data);
  [DllImport("user32.dll")] private static extern bool EnumDisplayMonitors(IntPtr hdc, IntPtr clip, EnumProc cb, IntPtr data);
  [DllImport("dxva2.dll")] private static extern bool GetNumberOfPhysicalMonitorsFromHMONITOR(IntPtr h, out uint n);
  [DllImport("dxva2.dll")] private static extern bool GetPhysicalMonitorsFromHMONITOR(IntPtr h, uint n, [Out] PHYSICAL_MONITOR[] arr);
  [DllImport("dxva2.dll")] private static extern bool SetMonitorBrightness(IntPtr h, uint brightness);
  [DllImport("dxva2.dll")] private static extern bool DestroyPhysicalMonitors(uint n, PHYSICAL_MONITOR[] arr);

  [StructLayout(LayoutKind.Sequential)]
  public struct GAMMARAMP {
    [MarshalAs(UnmanagedType.ByValArray, SizeConst=256)] public ushort[] Red;
    [MarshalAs(UnmanagedType.ByValArray, SizeConst=256)] public ushort[] Green;
    [MarshalAs(UnmanagedType.ByValArray, SizeConst=256)] public ushort[] Blue;
  }
  [DllImport("gdi32.dll")] private static extern bool SetDeviceGammaRamp(IntPtr hDC, ref GAMMARAMP ramp);
  [DllImport("gdi32.dll", CharSet=CharSet.Unicode)] private static extern IntPtr CreateDC(string driver, string device, string output, IntPtr initData);
  [DllImport("gdi32.dll")] private static extern bool DeleteDC(IntPtr hdc);

  public static void ApplyBrightness(uint target) {
    EnumDisplayMonitors(IntPtr.Zero, IntPtr.Zero, (IntPtr h, IntPtr dc, ref RECT rc, IntPtr d) => {
      uint n;
      if (GetNumberOfPhysicalMonitorsFromHMONITOR(h, out n) && n > 0) {
        var arr = new PHYSICAL_MONITOR[n];
        if (GetPhysicalMonitorsFromHMONITOR(h, n, arr)) {
          foreach (var pm in arr) SetMonitorBrightness(pm.hPhysicalMonitor, target);
          DestroyPhysicalMonitors(n, arr);
        }
      }
      return true;
    }, IntPtr.Zero);
  }
  public static void ApplyGamma(string dev, double rr, double gg, double bb) {
    IntPtr dc = CreateDC("DISPLAY", dev, null, IntPtr.Zero);
    if (dc == IntPtr.Zero) throw new Exception("CreateDC failed: " + dev);
    var ramp = new GAMMARAMP { Red = new ushort[256], Green = new ushort[256], Blue = new ushort[256] };
    for (int i = 0; i < 256; i++) {
      ramp.Red[i]   = (ushort)Math.Min(65535, (int)(i * 257.0 * rr));
      ramp.Green[i] = (ushort)Math.Min(65535, (int)(i * 257.0 * gg));
      ramp.Blue[i]  = (ushort)Math.Min(65535, (int)(i * 257.0 * bb));
    }
    SetDeviceGammaRamp(dc, ref ramp);
    DeleteDC(dc);
  }
}
'@
